import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,a as s}from"./chunks/M-S-LCS15b3.Bke3gG24.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as r,o as n,c as l,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Other Misc. Options","description":"","frontmatter":{},"headers":[],"relativePath":"use/misc.md","filePath":"use/misc.md"}'),p={name:"use/misc.md"};function m(c,i,h,u,b,g){return n(),l("div",null,[...i[0]||(i[0]=[d('<p>More options are available in this menu.<br> If they are hidden here it&#39;s probably because you won&#39;t need to change them every day, or you should leave them as they are unless instructed differently.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>   Less Common settings<br>    Other Misc. options</p></div><h5 id="run-collector-in-foreground" tabindex="-1">Run collector in foreground <a class="header-anchor" href="#run-collector-in-foreground" aria-label="Permalink to &quot;Run collector in foreground&quot;">​</a></h5><div class="info custom-block"><p class="custom-block-title">Note</p><p>Since Android 7 support was retired (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12th Jul 2026</a>) this is no longer a toggle you can turn off.</p></div><p>On Android 8.0 and above (the minimum supported version) xDrip always runs its collector as a foreground service to keep it from being put to sleep by Android. A persistent notification graph is therefore always shown, visible on the lock screen.</p><p>If you&#39;d rather not show the graph, the <code>Compact Persistent Notification</code> option in the same menu displays only the current glucose value instead.</p><div class="admonition xdripitem"><p class="admonition-title">Compact Persistent Notification <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Enable to hide the graph in the notification and display only the current glucose value.</p></div><img src="'+a+'" style="zoom:75%;"><h5 id="engineering-mode" tabindex="-1">Engineering mode <a class="header-anchor" href="#engineering-mode" aria-label="Permalink to &quot;Engineering mode&quot;">​</a></h5><p>Enables features that are potentially dangerous or untested. You do not need it to be enabled for restarting a G5 or an old G6 transmitter (new ones called Firefly can&#39;t be restarted). You actually don&#39;t need this to be enabled.</p><div class="admonition xdripitem"><p class="admonition-title">Engineering mode <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allows changing the most unsafe settings which could break everything!</p></div><p>To enable engineering mode enter or speak the <code>enable engineering mode</code> treatment.</p><p>You will be reminded monthly that engineering mode is on. Make sure you really need it, else keep it disabled.</p><img src="'+s+'" style="zoom:52%;"><h5 id="battery-optimization-prompt" tabindex="-1">Battery Optimization Prompt <a class="header-anchor" href="#battery-optimization-prompt" aria-label="Permalink to &quot;Battery Optimization Prompt&quot;">​</a></h5><p>Should be left <strong>disabled</strong>. xDrip needs <a href="./../install/install.html#authorize-background-activity">whitelisting</a> and shouldn&#39;t be subject to optimization.</p><div class="admonition xdripitem"><p class="admonition-title">Battery Optimization prompt <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> On Android 6+ ensure battery optimization is switched off (recommended)</p></div><h5 id="samsung-workarounds" tabindex="-1">Samsung Workarounds <a class="header-anchor" href="#samsung-workarounds" aria-label="Permalink to &quot;Samsung Workarounds&quot;">​</a></h5><p>Renamed to Wake Workarounds as other devices are not compliant.</p><h5 id="wake-workarounds" tabindex="-1">Wake Workarounds <a class="header-anchor" href="#wake-workarounds" aria-label="Permalink to &quot;Wake Workarounds&quot;">​</a></h5><p>Fixed a non-compliance with respect to some Android devices, now default for Samsung, Xiaomi, OnePlus, Oppo and Huawei.<br> Should be kept <strong>enabled</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Wake workarounds <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Use workarounds to avoid non-standard Android behavior of some handsets. Without this, collectors usually fail to get data.</p></div><p>Use Excessive Wakelocks is not required. They are additional &quot;wake-up&quot; messages sent by xDrip to your Android device to prevent it from going into sleep mode.</p><div class="admonition xdripitem"><p class="admonition-title">Use Excessive Wakelocks <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Older gratuitous wakelocks which can drain extra battery but might be needed for Nightwatch or Android Wear.</p></div><p>Display Predictive Values (old method) is deprecated. Use <a href="./predictions.html">Predictive Simulation</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Display Predictive Values <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Old method - Not Recommended! Attempts to predict readings each minute based on the past few values.</p></div><p>Proper Ongoing is mandatory for devices with Android 8 and above. Only visible with Engineering Mode enabled.</p><div class="admonition xdripitem"><p class="admonition-title">Proper Ongoing <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Use proper ongoing notification. Disabling this causes collector problems on Android 8+</p></div><h5 id="out-of-process-algorithm" tabindex="-1">Out of Process Algorithm <a class="header-anchor" href="#out-of-process-algorithm" aria-label="Permalink to &quot;Out of Process Algorithm&quot;">​</a></h5><p><a href="./OOP.html">Out Of Process Algorithm</a> enables the integration of an external plugin to give vendor-like BG values for Libre sensors or provide decoding of the Libre 2 EU sensor information.<br> If the external app doesn&#39;t exist on your phone or doesn&#39;t provide the information, xDrip will not display BG.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This option should only be enabled if using an Out Of Process algorithm version 1 (OOP1).<br> It must be disabled for OOP2.</p></div><div class="admonition xdripitem"><p class="admonition-title">Out of process Libre algorithm <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use an out of process (OOP) Libre algorithm. (BluCon/NFC/LibreAlarm)</p></div><h5 id="oop2" tabindex="-1">OOP2 <a class="header-anchor" href="#oop2" aria-label="Permalink to &quot;OOP2&quot;">​</a></h5><p>OOP2 is mandatory to handle data from Libre 14 days US, Libre 2/2+ EU.</p><div class="admonition xdripitem"><p class="admonition-title">OOP2 algorithm calibration</p><p> Apply xDrip calibration methods on OOP2 data.</p></div><p>You can use OOP2 in different ways:</p><ul><li>No calibration generates vendor-like values (native mode) without the need of calibrating. It doesn&#39;t mean that results are not calibrated (raw) but a vendor-like algorithm is applied (like the Libre 1 reader).</li><li>Calibrate based on raw uses the sensor raw data (no temperature correction) like Libre 1. You will use the xDrip calibration algorithm. <strong>Shipped default.</strong></li><li>Calibrate based on glucose allows you to apply xDrip calibration to native values. Raw data are transformed using the vendor-like algorithm, then fed to the xDrip calibration algorithm.</li></ul><div class="admonition xdripitem"><p class="admonition-title">OOP2 algorithm calibration</p><p> No calibration       ○<br>  Calibrate based on raw   ●<br>  Calibrate based on glucose (experimental)  ○</p></div><p>Smooth Libre data averages over 5 measurements. This will also delay readings.<br> If this option doesn&#39;t bring the improvement expected, also try <a href="./display.html#smooth-sensor-noise">Smooth Sensor Noise</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Smooth Libre data <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use average of 5 points to get smoother Libre data</p></div><p>Retrieve Libre History is required for BluCon bridges. Other bridges perform backfilling automatically.</p><div class="admonition xdripitem"><p class="admonition-title">Retrieve Libre history <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Retrieve missed history from BluCon device when reconnecting to sensor.</p></div><p>Libre 1-minute display is still under development. xDrip displays BG values every 5 minutes. With the <a href="./../install/li3.html">Li3</a> data source, readings are stored every minute when it&#39;s enabled.</p><div class="admonition xdripitem"><p class="admonition-title">Libre 1-minute <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Accept data at one-minute intervals from Libre. Reboot your phone for changes to take effect.</p></div><h5 id="li3" tabindex="-1">Li3 <a class="header-anchor" href="#li3" aria-label="Permalink to &quot;Li3&quot;">​</a></h5><p>The Li3 settings (Account ID, Official app, Smooth Li3 readings) are explained on the <a href="./../install/li3.html#li3-settings">Li3</a> page.</p><h5 id="1-min-inter-app-broadcast" tabindex="-1">1-min Inter-app broadcast <a class="header-anchor" href="#1-min-inter-app-broadcast" aria-label="Permalink to &quot;1-min Inter-app broadcast&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">1-min Inter-app broadcast <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Accept data at one-minute intervals from Inter-app broadcast. Reboot your phone for changes to take effect.</p></div><p>Accept readings every minute instead of every 5 minutes from the <a href="./../install/640_670.html">Inter-app broadcast</a> data source. Reboot the phone after changing it. Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9th Sep 2026</a> this no longer requires engineering mode (it was named &quot;640G/Eversense 1-minute&quot; before).</p><p>The option below is always greyed out in the app: it cannot be enabled.</p><div class="admonition xdripitem"><p class="admonition-title">NOT FOR PRODUCTION USE <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',53)])])}const w=r(p,[["render",m]]);export{x as __pageData,w as default};
